# Generated by Descant: acceptance tests.

# frozen_string_literal: true

# The shared test doubles are what every relay example rests on, so a switch
# that silently did nothing would let those examples pass for the wrong reason.
RSpec.describe TimekeepingRelaySpec::MemoryOutboxSource do
  it "fail_next_mark! loses only the next mark and leaves the row unsent" do
    row = described_class.row(1)
    source = described_class.new([row])

    expect(source.fail_next_mark!).to be_nil
    expect { source.mark_sent([1]) }.to raise_error(IOError)
    expect(source.lost_marks).to eq([[1]])
    expect(source.mark_calls).to be_empty
    expect(source.sent_positions).to be_empty
    expect(source.unsent_after(0, 10)).to eq([row])

    # Only the next mark fails; the one after it succeeds.
    expect { source.mark_sent([1]) }.not_to raise_error
    expect(source.mark_calls).to eq([[1]])
    expect(source.lost_marks).to eq([[1]])
    expect(source.sent_positions).to eq([1])
    expect(source.unsent_after(0, 10)).to be_empty
  end

  it "add puts a row committed after construction below already sent positions back in the unsent rows" do
    source = described_class.new([12, 3, 7].map { |position| described_class.row(position) })
    source.mark_sent([3, 7, 12])

    source.add(described_class.row(5))

    expect(source.unsent_after(0, 10).map { |row| row["outbox_position"] }).to eq([5])
    expect(source.sent_positions).to contain_exactly(3, 7, 12)
  end

  it "row keeps its defaults and accepts an entry id and generation" do
    expect(described_class.row(4)).to eq(
      "generation" => 1, "outbox_position" => 4,
      "entry" => { "id" => 4, "company_id" => 1, "version" => 1 }
    )
    expect(described_class.row(1, id: 301, generation: 2)).to eq(
      "generation" => 2, "outbox_position" => 1,
      "entry" => { "id" => 301, "company_id" => 1, "version" => 1 }
    )
  end
end

RSpec.describe TimekeepingRelaySpec::FakeRelayEndpoint do
  def delivering_projection(operations: ["deliver"], name: "timekeeping")
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name:, operations:)
    [TimekeepingContract::FakeRelay.new(source: timekeeping), credential]
  end

  def batch_of(*rows)
    { "schema_version" => 1, "snapshots" => rows }
  end

  it "keeps no deliver path of its own and posts to HttpEndpoint::DELIVER_PATH" do
    # "Make MemoryOutboxSource (with a fail-next-mark switch) and FakeRelayEndpoint (with scripted statuses, using TimekeepingRelay::HttpEndpoint::DELIVER_PATH) the only test doubles."
    expect(described_class.const_defined?(:DELIVER_PATH, false)).to be(false)

    projection, credential = delivering_projection
    paths = []
    call = projection.method(:call)
    projection.define_singleton_method(:call) do |method, path, **options|
      paths << path
      call.call(method, path, **options)
    end
    endpoint = described_class.new(projection:, credential:)

    expect(endpoint.deliver(batch_of(TimekeepingRelaySpec::MemoryOutboxSource.row(2)), idempotency_key: "key-1").status).to eq(200)
    expect(paths).to eq([TimekeepingRelay::HttpEndpoint::DELIVER_PATH])
  end

  it "answers a scripted 503 without reaching the projection, then the next post reaches it" do
    projection, credential = delivering_projection
    endpoint = described_class.new(projection:, credential:,
                                   answers: [TimekeepingRelay::Response.new(status: 503, body: {})])
    batch = batch_of(TimekeepingRelaySpec::MemoryOutboxSource.row(1, id: 10))

    expect(endpoint.deliver(batch, idempotency_key: "key-1").status).to eq(503)
    expect(projection.projected_entry(10)).to be_nil

    recovered = endpoint.deliver(batch, idempotency_key: "key-1")
    expect(recovered.status).to eq(200)
    expect(recovered.body).to eq("applied" => 1, "ignored" => 0)
    expect(projection.projected_entry(10)).to include("id" => 10, "version" => 1)
  end

  it "records each batch, key and answer once, scripted and projected alike" do
    projection, credential = delivering_projection
    endpoint = described_class.new(projection:, credential:,
                                   answers: [TimekeepingRelay::Response.new(status: 503, body: {})])
    batch = batch_of(TimekeepingRelaySpec::MemoryOutboxSource.row(3))

    endpoint.deliver(batch, idempotency_key: "key-a")
    endpoint.deliver(batch, idempotency_key: "key-b")

    expect(endpoint.posts.map { |post| post[:key] }).to eq(%w[key-a key-b])
    expect(endpoint.posts.map { |post| post[:batch] }).to eq([batch, batch])
    expect(endpoint.posts.map { |post| post[:answer].status }).to eq([503, 200])
    expect(endpoint.idempotency_keys).to eq(%w[key-a key-b])
  end

  # The 403 must come from the real consumer fake's credential check, not from a script.
  it "passes on the consumer's 403 for a credential without the deliver operation and projects nothing" do
    projection, credential = delivering_projection(name: "reporting", operations: ["read"])
    endpoint = described_class.new(projection:, credential:)

    response = endpoint.deliver(batch_of(TimekeepingRelaySpec::MemoryOutboxSource.row(4)), idempotency_key: "key-403")

    expect(response.status).to eq(403)
    expect(response.delivered?(1)).to be(false)
    expect(endpoint.posts.map { |post| [post[:key], post[:answer].status] }).to eq([["key-403", 403]])
    expect(projection.projected_entry(4)).to be_nil
  end

  # A missing script must fail loudly, never answer as if it were delivered.
  it "raises once the scripted answers run out with no projection, after recording the post" do
    endpoint = described_class.new(
      answers: [TimekeepingRelay::Response.new(status: 200, body: { "applied" => 1, "ignored" => 0 })]
    )
    source = TimekeepingRelaySpec::MemoryOutboxSource.new(
      [TimekeepingRelaySpec::MemoryOutboxSource.row(1), TimekeepingRelaySpec::MemoryOutboxSource.row(2)]
    )

    expect { TimekeepingRelay::Relay.new(source:, endpoint:).deliver(limit: 1) }
      .to raise_error(ArgumentError, /no scripted answer left/)
    expect(source.mark_calls).to eq([[1]])
    expect(endpoint.posts.size).to eq(2)
  end
end
